/**
 * The optional Review-pass agent (composes with either delegation mode; on
 * by default via `execution.json`'s `reviewEnabled`). Kept in its own list
 * (rather than merged into `REGULAR_AGENTS` or `LEAD_AGENTS`) so its
 * install/remove is driven by the `reviewEnabled` toggle instead of by
 * `delegation_mode` — a project can be Direct+Review, Team-Leads+Review,
 * or either mode with Review off. Unlike `LEAD_AGENTS`, a reviewer is a
 * normal spawnable leaf worker: it owns no team of its own, so the
 * ready-test skill (which excludes only `tier: lead`) spawns it like any
 * other agent. `tier: "reviewer"` exists solely as the safety marker
 * `agentMarkdownTier` uses before deleting a `reviewer.md` file when the
 * toggle is turned off — mirrors the `tier: "lead"` removal safety check.
 */
export const REVIEWER_AGENTS: PackAgent[] = [
  {
    id: "reviewer",
    name: "Reviewer",
    model: "sonnet",
    tier: "reviewer",
    role:
      "Reviews a specialist's COMPLETED work for a task — reads the diff, checks it against the task's intent and acceptance criteria, and flags bugs, regressions, or quality issues it finds. Returns either APPROVE or a concise list of required changes. Does not implement fixes itself; a required change goes back to the specialist that authored the work.",
    keywords: "review|approve|correctness|regression",
  },
];

/**
 * The project-appropriate worker roster to install, given whether the
 * project is a UEFN project. `search-retrieval` and `primary-agent` (the
 * Wildcard Agent) are ALWAYS included, in every project type — both are
 * project-agnostic: search/retrieval work and keyword-unmatched catch-all
 * work exist regardless of tech stack. Prior to this, `primary-agent` had no
 * install path at all despite being the documented default
 * `fallback_agent` (see `_defaultAgentRoutingConfig` in panel.ts), so
 * keyword-unmatched tasks had no real agent file to route to and silently
 * fell back to the orchestrator doing the work itself. Non-UEFN projects
 * additionally get `coding-specialist` and `ux-ui-designer`; UEFN projects
 * get neither (a UEFN pack install brings its own `uefn-auditor` and
 * `verse-expert`, and this file's `REVIEWER_AGENTS` reviewer would conflict
 * with `uefn-auditor` as a verification gate, so it is likewise withheld —
 * see `_handleInstallHooks` in panel.ts). Pure: reads only `REGULAR_AGENTS`.
 */
export function workerAgentsForProject(isUefn: boolean): PackAgent[] {
  const ids = isUefn
    ? ["search-retrieval", "primary-agent"]
    : ["search-retrieval", "primary-agent", "coding-specialist", "ux-ui-designer"];
  return ids
    .map((id) => REGULAR_AGENTS.find((a) => a.id === id))
    .filter((a): a is PackAgent => a !== undefined);
}

/**
 * The generic worker agents that conflict with the UEFN pack's own
 * Verse-specialist agents when both are installed on the same project:
 * `reviewer` (generic code reviewer) would otherwise compete with
 * `uefn-auditor` (the Verse auditor / verification gate) and
 * `coding-specialist` (generic implementer) would compete with
 * `verse-expert` (the Verse coder) — the same routing keywords pointing at
 * two agents means task routing becomes ambiguous, and worse, could route
 * Verse work to an agent with no Verse knowledge. Order here is canonical;
 * {@link conflictingUefnAgents} preserves it regardless of input order.
 * `ux-ui-designer` is deliberately NOT included — the UEFN pack has no
 * competing design agent.
 */

/**
 * Foreign-LLM reviewer/worker agents that route review or delegated work
 * through a non-Anthropic-native backend (OpenAI Codex, Google Gemini,
 * Moonshot Kimi K2 / any OpenAI-compatible endpoint, or the user's own
 * Claude CLI subscription login) via the matching MCP server in
 * media/mcp/catalog.json (ids: codex, gemini, openai-compatible,
 * claude-cli). Each carries a `backend` block (see src/core/agentBackend.ts)
 * and a hand-authored `body` overriding the generic template — these are
 * the canonical sources for the four agents formerly hand-authored only as
 * .claude/agents/*.md with no shipped install path (a fresh install never
 * got them). Kept in a SEPARATE list from REGULAR_AGENTS: unlike the core
 * roster, these require an optional MCP server most projects won't have
 * configured, so they ship as the opt-in "Multi-LLM agents" pack
 * (media/packs/catalog.json) rather than being installed unconditionally.
 */
